mapper.sql:
WHERE h.deleted = 0
AND (o.code LIKE #{f.keyword} OR o.name LIKE #{f.keyword} OR o.short_name LIKE #{f.keyword})
AND h.year = #{f.year}
AND h.status = #{f.status}

WHERE d.deleted = 0
  AND (k.parent_id IS NULL OR NOT EXISTS (SELECT 1 FROM kpi_assignment_detail pd WHERE pd.kpi_id = k.parent_id AND pd.year = d.year AND pd.deleted = 0))
AND (k.code LIKE #{f.keyword} OR k.name LIKE #{f.keyword}
  OR EXISTS (SELECT 1 FROM kpi c WHERE c.parent_id = k.id AND c.deleted = 0 AND (c.code LIKE #{f.keyword} OR c.name LIKE #{f.keyword})))
AND d.year = #{f.year}
AND k.perspective_id = #{f.perspectiveId}

GROUP BY d.kpi_id, d.year

  HAVING (CASE WHEN SUM(d.status = 'DANG_SOAN') > 0 THEN 'DANG_SOAN' WHEN SUM(d.status = 'DA_DIEU_CHINH') > 0 THEN 'DA_DIEU_CHINH' ELSE 'DA_GIAO' END) = #{f.status}

mapper.select:

WHERE d.deleted = 0 AND k.parent_id IN #{i}
AND d.year IN #{y}

GROUP BY d.kpi_id, d.year ORDER BY k.code
